from django import formsfrom .models import Appointment, Membership, ContactMessageclass AppointmentForm(forms.ModelForm):    class Meta:        model = Appointment        fields = ['name', 'email', 'phone', 'service_type', 'appointment_date', 'appointment_time', 'details', 'status']        widgets = {            'appointment_date': forms.DateInput(attrs={'type': 'date'}),            'appointment_time': forms.TimeInput(attrs={'type': 'time'}),            'details': forms.Textarea(attrs={'rows': 3}),        }class MembershipForm(forms.ModelForm):    class Meta:        model = Membership        fields = ['full_name', 'email', 'phone', 'membership_type', 'organization', 'message', 'status']        widgets = {            'message': forms.Textarea(attrs={'rows': 3}),        }class ContactMessageForm(forms.ModelForm):    class Meta:        model = ContactMessage        fields = ['name', 'email', 'subject', 'message', 'is_read']        widgets = {            'message': forms.Textarea(attrs={'rows': 3}),        }